      const strength = parseFloat(el.getAttribute('data-strength') || '0.35');
      const radius = parseFloat(el.getAttribute('data-radius') || '120');
      const damping = parseFloat(el.getAttribute('data-damping') || '18');
      const maxDisplacement = parseFloat(el.getAttribute('data-max-displacement') || '36');

