        isHovered = true;
        startRaf();
      });

      el.addEventListener('pointerleave', () => {
        isHovered = false;
        target.x = 0;
        target.y = 0;
        startRaf();
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMagneticButtons);
  } else {
    initMagneticButtons();
  }
  document.addEventListener('astro:page-load', initMagneticButtons);
</script>

